from typing import List
class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        last = {}
        for i, v in enumerate(nums):
            last[v] = i
        cuts = far = 0
        for i in range(len(nums) - 1):
            far = max(far, last[nums[i]])
            if far == i:
                cuts += 1
        return pow(2, cuts, 10 ** 9 + 7)

