var numberOfGoodPartitions = function(nums) {
    const MOD = 1e9 + 7;
    const last = new Map();
    nums.forEach((v, i) => last.set(v, i));
    let cuts = 0, far = 0;
    for (let i = 0; i + 1 < nums.length; i++) {
        far = Math.max(far, last.get(nums[i]));
        if (far === i) cuts++;
    }
    let ans = 1;
    for (let i = 0; i < cuts; i++) ans = ans * 2 % MOD;
    return ans;
};
